import report from '../../generated/test-report.json';
import type { TestReport as Report } from '../../lib/devtools';
import { Card, Status } from '../ui';

/** G31 — per-suite test counts, generated by scripts/test-report.ts from a real vitest run. */
export function TestReport() {
  const r = report as Report;
  const t = r.totals;
  const max = Math.max(...r.suites.map((s) => s.tests), 1);
  return (
    <Card title="Test report" aside={<span className={`pill ${t.failed ? 'pill-warn' : 'pill-ok'}`}>{t.failed ? `${t.failed} failing` : 'all passing'}</span>}>
      <div className="dev-stats">
        <div>
          <b>{t.tests}</b>
          <span>tests</span>
        </div>
        <div>
          <b>{t.passed}</b>
          <span>passed</span>
        </div>
        <div>
          <b>{t.failed}</b>
          <span>failed</span>
        </div>
        <div>
          <b>{t.suites}</b>
          <span>suites</span>
        </div>
      </div>
      <p className="small muted">
        {r.runner} · generated {new Date(r.generatedAt).toLocaleString()} by <code>npx tsx scripts/test-report.ts</code>. Foundry (<code>forge test</code>) and SolidCash (<code>solidhat test</code>) suites run separately in <code>pnpm test</code>.
      </p>
      {t.failed > 0 && <Status kind="warn">Some tests failed in the recorded run.</Status>}
      <details open>
        <summary>Per suite ({r.suites.length})</summary>
        <div className="table-scroll">
          <table className="table dev-suites">
            <thead>
              <tr>
                <th>Suite</th>
                <th>Tests</th>
                <th>Pass</th>
                <th>Fail</th>
                <th>Time</th>
              </tr>
            </thead>
            <tbody>
              {r.suites.map((s) => (
                <tr key={s.file}>
                  <td className="mono small">
                    {s.file.replace(/^tests\//, '')}
                    <div className="dev-bar" style={{ width: `${(s.tests / max) * 100}%` }} />
                  </td>
                  <td>{s.tests}</td>
                  <td className="dev-ok">{s.passed}</td>
                  <td className={s.failed ? 'dev-bad' : 'muted'}>{s.failed}</td>
                  <td className="small muted">{(s.ms / 1000).toFixed(1)} s</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </details>
    </Card>
  );
}
